import asyncio
import socket

PRINTER_IP = "192.168.1.69"
PRINTER_PORT = 9100

# 43mm x 29mm @ 203dpi (8 dots/mm)
LABEL_W = 344
LABEL_H = 232
MARGIN = 10
GAP = 6

FONT_H = 20
FONT_W = 14
TITLE_FONT_H = 26
TITLE_FONT_W = 20
TITLE_LINE_GAP = 2
TITLE_CHAR_SPACING = 1
TITLE_SHIFT_LEFT = 24  # ~3 mm @ 203 dpi
TITLE_ALLOW_OVERLAP = 24  # permite meterse en zona blanca del logo (~3 mm)

LOGO_MAX_W = 112
LOGO_MAX_H = 80
TITLE_LINE_1 = "TONELERIA"
TITLE_LINE_2 = "ANTONIO"
TITLE_LINE_3 = "PAEZ LOBATO"

LOGO_W = 112
LOGO_H = 80
LOGO_GFA = "^GFA,1120,1120,14,"


def send_raw_zpl(zpl: str):
    data = zpl.encode("utf-8")
    with socket.create_connection((PRINTER_IP, PRINTER_PORT), timeout=5) as s:
        s.sendall(data)


def code128_modules_for_n_chars(n: int) -> int:
    # Start + data + check + stop + termination
    return 11 * n + 37


def build_barcode128_logo_label(value: str, copies: int = 1) -> str:
    if not value:
        raise ValueError("El valor no puede estar vacio.")
    if copies < 1:
        raise ValueError("copies debe ser >= 1")

    avail_w = LABEL_W - 2 * MARGIN
    modules = code128_modules_for_n_chars(len(value))
    module_width = max(1, min(3, avail_w // modules))
    barcode_w = modules * module_width
    bar_x = (LABEL_W - barcode_w) // 2

    # Bloque superior alineado al ancho del barcode.
    header_y = MARGIN
    logo_x = bar_x
    logo_y = header_y + max(0, (LOGO_MAX_H - LOGO_H) // 2)

    title_right = LABEL_W - MARGIN
    # Bloque de 3 lineas dentro del margen derecho de la etiqueta.
    title_left_min = logo_x + LOGO_W + 8 - TITLE_ALLOW_OVERLAP
    line2_estimated_w = len(TITLE_LINE_2) * (TITLE_FONT_W + TITLE_CHAR_SPACING)
    line3_estimated_w = len(TITLE_LINE_3) * (TITLE_FONT_W + TITLE_CHAR_SPACING)
    title_max_w = max(20, title_right - title_left_min)
    title_w = min(title_max_w, max(20, line2_estimated_w, line3_estimated_w))
    title_x = title_right - title_w - TITLE_SHIFT_LEFT
    title_x = max(title_left_min, title_x)
    title_block_h = (3 * TITLE_FONT_H) + (2 * TITLE_LINE_GAP)
    title_y = logo_y + max(0, (LOGO_H - title_block_h) // 2)

    header_h = max(LOGO_H, title_block_h) + 8
    barcode_top = header_y + header_h

    bar_h = max(40, LABEL_H - barcode_top - GAP - FONT_H - MARGIN)
    bar_y = barcode_top
    text_y = bar_y + bar_h + GAP
    text_x = MARGIN
    text_w = LABEL_W - (2 * MARGIN)
    title_y_2 = title_y + TITLE_FONT_H + TITLE_LINE_GAP
    title_y_3 = title_y_2 + TITLE_FONT_H + TITLE_LINE_GAP

    return f"""
    ^XA
    ^MMT
    ^PW366
    ^LL232
    ^LS0
    ^FO16,4^GFA,1597,8358,42,:Z64::BAF4
    ^PQ1,0,1,Y
    ^XZ"""
    
    return f"""^XA
^PW{LABEL_W}
^LL{LABEL_H}
^CI28
^LH0,0

^FO{logo_x},{logo_y}
{LOGO_GFA}

^FO{title_x},{title_y}
^A0N,{TITLE_FONT_H},{TITLE_FONT_W}
^FB{title_w},1,0,C,0
^FD{TITLE_LINE_1}^FS
^FO{title_x + 1},{title_y}
^A0N,{TITLE_FONT_H},{TITLE_FONT_W}
^FB{title_w},1,0,C,0
^FD{TITLE_LINE_1}^FS

^FO{title_x},{title_y_2}
^A0N,{TITLE_FONT_H},{TITLE_FONT_W}
^FB{title_w},1,0,C,0
^FD{TITLE_LINE_2}^FS
^FO{title_x + 1},{title_y_2}
^A0N,{TITLE_FONT_H},{TITLE_FONT_W}
^FB{title_w},1,0,C,0
^FD{TITLE_LINE_2}^FS

^FO{title_x},{title_y_3}
^A0N,{TITLE_FONT_H},{TITLE_FONT_W}
^FB{title_w},1,0,C,0
^FD{TITLE_LINE_3}^FS
^FO{title_x + 1},{title_y_3}
^A0N,{TITLE_FONT_H},{TITLE_FONT_W}
^FB{title_w},1,0,C,0
^FD{TITLE_LINE_3}^FS

^FO{bar_x},{bar_y}
^BY{module_width},2,{bar_h}
^BCN,,N,N,N
^FD{value}^FS

^FO{text_x},{text_y}
^A0N,{FONT_H},{FONT_W}
^FB{text_w},1,0,C,0
^FD{value}^FS

^PQ{copies}
^XZ
"""


async def print_label(value: str, copies: int = 1):
    a = ""
    for i in range(20):
        a = a + build_barcode128_logo_label(f"TEST-{i+1:03d}", copies=copies)
    send_raw_zpl(a)
    #await asyncio.sleep(0.5)


if __name__ == "__main__":
    #print_label("A1B2C3D4E5F6G7H-000*", copies=1)
    asyncio.run(print_label("", copies=1))
